      "ar": "أَمَّن يُجِيبُ الْمُضْطَرَّ إِذَا دَعَاهُ وَيَكْشِفُ السُّوءَ وَيَجْعَلُكُمْ خُلَفَاءَ الْأَرْضِ أَءِلَٰهٌ مَّعَ اللَّهِ قَلِيلًا مَّا تَذَكَّرُونَ",
      "translit": "Amman yujību l-muḍṭarra idhā daʿāhu wayakshifu s-sūʾa wayajʿalukum khulafāʾa l-ʾarḍi aʾilāhun maʿa llāhi qalīlan mā tadhakkarūn",
