        "tr": {
          "auteur": "Diyanet İşleri Başkanlığı",
          "texte": "Kendilerine söylenmiş olan başlarına geldiği zaman, yerden bir çeşit hayvan çıkarırız ki o, onlara, insanların ayetlerimize kesin olarak inanmadıkların söyler"
        }
